/* V9: CONSOLE MECHANICAL LAYOUT — Rack owns freed height, never the live fader.
   Fader height is invariant when ROUTE / SEND are expanded/collapsed. Master and
   rail are siblings in the same flex-height contract, not independent rulers.
   The rack becomes the variable-height processing workspace. */.console-body:not(.collapsed-fx) .section-rail .rail-cell.fader{
  flex:0 0 var(--fader-fixed-h)!important;
  height:var(--fader-fixed-h)!important;
  min-height:var(--fader-fixed-h)!important;
  max-height:var(--fader-fixed-h)!important;
}
.console-body:not(.collapsed-fx) .section-rail .rail-cell.fx{
  flex:1 1 var(--fx-h)!important;
  height:auto!important;min-height:23px!important;max-height:none!important;
}
.console-body.collapsed-fx .strip .fx-section,
.console-body.collapsed-fx .section-rail .rail-cell.fx{
  flex:0 0 23px!important;height:23px!important;min-height:23px!important;
  max-height:23px!important;
}
/* Only if the operator intentionally COLLAPSES FX does the fader absorb slack. */
.console-body.collapsed-fx .strip .fader-section,
.console-body.collapsed-fx .section-rail .rail-cell.fader{
  flex:1 1 var(--fader-fixed-h)!important;
  height:auto!important;min-height:130px!important;max-height:none!important;
}
@media(max-height:680px){
  .console-body{--fader-fixed-h:clamp(135px,28vh,190px);--route-h:56px;--pan-h:36px;--switch-h:40px;--footer-h:45px}
}
/* Hardware continuity: satin upper plates, subtle milled lines, consistent hierarchy. */
.console-body .strip .split-count{font:600 9px/1.2 Consolas,monospace;color:#b5e8f1;
 border:1px solid #5d8291;border-radius:2px;padding:1px 2px;white-space:nowrap}

/* V11 — FL-style selectable source/target wiring in the MIDDLE (SEND/BUS) strip.
   Only visual reference. Default SEND rack collapsed, its wire tray stays visible.
   Do not move hardware faders, clip VU or shrink expandable FX slot rack. */
.console-body.collapsed-send{--send-h:53px!important}
.console-body:not(.collapsed-send){--send-h:129px!important}
.console-body .section-rail .rail-cell.send{
  height:var(--send-h)!important;min-height:var(--send-h)!important;
  flex:0 0 var(--send-h)!important;
  background:linear-gradient(#263b45,#1d303a)!important;
  color:#a4d6e2!important;
}
.console-body .strip .send-section{
  display:flex!important;flex-direction:column!important;
  height:var(--send-h)!important;min-height:var(--send-h)!important;
  flex:0 0 var(--send-h)!important;overflow:hidden!important;
}
.tracks-viewport{position:relative!important;isolation:isolate}
.routing-wire-overlay{
  position:absolute;inset:0;width:100%;height:100%;overflow:hidden;pointer-events:none;contain:paint;
}
@media(max-width:1000px){.wire-legend{max-width:220px}}
@media(max-height:680px){.console-body.collapsed-send{--send-h:49px!important}}
.routing-wire-overlay{filter:drop-shadow(0 0 1.2px #5cc67f40)}
@media(max-width:1250px){.wire-legend{max-width:145px}.wire-mode-select{max-width:112px;font-size:9px}.wire-master{min-width:55px;padding:0 4px}}
@media(max-width:970px){.wire-legend{display:none}.wire-mode-label{display:none}}

/* V12-P0 CONVERGENCE: native owner's latest passing physical geometry baseline.
   The center wire strip costs 30px more than the pre-wire SEND row; recover
   its space from compact top chrome and fixed mechanical label wells, not
   from FX visibility or any accidental ROUTE-driven fader movement. */
.window-title{height:23px!important;min-height:23px!important;flex:0 0 23px!important}
.command-bar{height:35px!important;min-height:35px!important;flex:0 0 35px!important}
.status-bar{height:20px!important;min-height:20px!important;flex:0 0 20px!important}
.console-body{
 --identity-h:25px!important;--footer-h:48px!important;
 --pan-h:37px;--switch-h:40px;
 --p0-fader-standard:clamp(215px,calc(100dvh - 510px),600px);
 --p0-fader-h:var(--p0-fader-standard);
 --fader-fixed-h:var(--p0-fader-h); /* feeds earlier high-specificity fader selectors */
}
.console-body:not(.collapsed-send){
 --p0-fader-h:max(150px,calc(var(--p0-fader-standard) - 80px));
}
@media(max-height:680px){
 .console-body{--p0-fader-standard:clamp(155px,calc(100dvh - 505px),300px)}
 .console-body:not(.collapsed-send){--p0-fader-h:max(118px,calc(var(--p0-fader-standard) - 80px))}
}
.console-body .strip .fader-section,
.console-body .section-rail > .rail-cell.fader{
 flex:0 0 var(--p0-fader-h)!important;height:var(--p0-fader-h)!important;
 min-height:var(--p0-fader-h)!important;max-height:var(--p0-fader-h)!important;
}


/* When intentionally collapsing the entire FX section, unused room may return
   to the physical fader, but never when only ROUTE is collapsed. */


/* V13 physical routing bay — no old DAW send form in mixer strips.
   Compact: 80px, Expanded: 160px; +80px fold is balanced by P0 fader
   budget on expand, preserving the rack's four legible insert rows. */.console-body.wire-routing-v13:not(.collapsed-send){--send-h:160px!important}
.console-body.wire-routing-v13 .section-rail .rail-cell.send{
 font:600 12px Arial,sans-serif!important;
 color:#b1dae4!important;
}
.console-body.wire-routing-v13 .section-rail .rail-cell.send::after{
 content:"WIRE";display:block;font:600 7px/8px Arial,sans-serif;
 color:#78afb5;letter-spacing:.4px;
}
.console-body.wire-routing-v13:not(.collapsed-send) .section-rail .rail-cell.send::after{content:"PATCH"}
.console-body.wire-routing-v13 .strip .send-header,
.console-body.wire-routing-v13 .strip .send-select,
.console-body.wire-routing-v13 .strip .sendlevel,
.console-body.wire-routing-v13 .strip .send-slot{display:none!important}
.routing-wire-overlay{z-index:6;pointer-events:none!important}
/* Keep compact routing visible on short stage laptops; no legacy form resurfaces. */
@media(max-height:680px){
 .console-body.wire-routing-v13:not(.collapsed-send){--send-h:138px!important}
 .console-body.wire-routing-v13 .strip .wire-deck{padding-top:3px}
 .console-body.wire-routing-v13 .strip .wire-deck-status{display:none}
}
/* V13 OPERATOR CONSOLE: flat anodized metal and a STATIONARY lower block.
   ROUTE / FX / SEND own the entire flexible upper region; PAN + M/S/PFL +
   FADER + footer never resize or move when any section is toggled. Styles
   deliberately live at the end, after legacy V9-V12 chrome precedence. */
.console-body{
 --p0-fader-h:var(--v13-fader-h)!important;
 --fader-fixed-h:var(--v13-fader-h)!important;
}
.console-body .strip .route-section,
.console-body.collapsed-route .strip .route-section,
.console-body .section-rail>.rail-cell.route{
 flex:0 0 var(--route-h)!important;
 height:var(--route-h)!important;
 min-height:var(--route-h)!important;
 max-height:var(--route-h)!important;
}
.console-body .strip .send-section,
.console-body.collapsed-send .strip .send-section,
.console-body .section-rail>.rail-cell.send{
 flex:0 0 var(--send-h)!important;
 height:var(--send-h)!important;
 min-height:var(--send-h)!important;
 max-height:var(--send-h)!important;
}
/* FX absorbs differences in both ROUTE and SEND height, on every channel
   and on the left rail. The min accommodates 4×25px rows + 25px header. */
.console-body:not(.collapsed-fx) .strip .fx-section,
.console-body:not(.collapsed-fx) .section-rail>.rail-cell.fx{
 flex:1 1 125px!important;height:auto!important;
 min-height:125px!important;max-height:none!important;
}
.console-body.collapsed-fx .strip .fx-section,
.console-body.collapsed-fx .section-rail>.rail-cell.fx{
 flex:0 0 23px!important;height:23px!important;
 min-height:23px!important;max-height:23px!important;
}
/* FX is intentionally closed: SEND (if open) absorbs the spare upper height,
   otherwise the upper region leaves a deliberate gap, never fader stretch. */
.console-body.collapsed-fx:not(.collapsed-send) .strip .send-section,
.console-body.collapsed-fx:not(.collapsed-send) .section-rail>.rail-cell.send{
 flex:1 1 var(--send-h)!important;
 height:auto!important;max-height:none!important;
}
.console-body .strip .pan-section,
.console-body .section-rail>.rail-cell.pan{
 height:var(--pan-h)!important;min-height:var(--pan-h)!important;
 max-height:var(--pan-h)!important;flex:0 0 var(--pan-h)!important;
}
.console-body .strip .switch-section,
.console-body .section-rail>.rail-cell.switch{
 height:var(--switch-h)!important;min-height:var(--switch-h)!important;
 max-height:var(--switch-h)!important;flex:0 0 var(--switch-h)!important;
}
.console-body .strip .fader-section,
.console-body.collapsed-fx .strip .fader-section,
.console-body.collapsed-fx.collapsed-send .strip .fader-section,
.console-body .section-rail>.rail-cell.fader,
.console-body.collapsed-fx .section-rail>.rail-cell.fader,
.console-body.collapsed-fx.collapsed-send .section-rail>.rail-cell.fader{
 height:var(--v13-fader-h)!important;min-height:var(--v13-fader-h)!important;
 max-height:var(--v13-fader-h)!important;flex:0 0 var(--v13-fader-h)!important;
}
.console-body .strip .bottom-section,
.console-body .section-rail>.rail-cell.footer{
 height:var(--footer-h)!important;min-height:var(--footer-h)!important;
 max-height:var(--footer-h)!important;flex:0 0 var(--footer-h)!important;
}
/* PAN is the boundary: keep lower console docked to the bottom when all
   upper compartments are intentionally collapsed. */
.console-body.collapsed-fx.collapsed-send .strip .pan-section,/* V14: THREE-way collapse is the sole exception to the anchored lower
   deck. CSS flex consumes freed upper space with a taller fader rising toward
   the collapsed controls; PAN/SOLO follow upward as a coherent unit. For any
   other combination, original deck geometry remains unchanged. No resize JS. */
.console-body.collapsed-route.collapsed-fx.collapsed-send .strip .pan-section,
.console-body.collapsed-route.collapsed-fx.collapsed-send .section-rail>.rail-cell.pan{
 margin-top:0!important;
}
.console-body.collapsed-route.collapsed-fx.collapsed-send .strip .fader-section,
.console-body.collapsed-route.collapsed-fx.collapsed-send .section-rail>.rail-cell.fader{
 flex:1 1 var(--v13-fader-h)!important;
 height:auto!important;
 min-height:var(--v13-fader-h)!important;
 max-height:none!important;
}
/* Colored channel nameplates and LEDs remain meaningful on a dark, satin,
   untextured metal desk. Shadows only define seams and mechanical recesses. */
/* FLAT plate language: no large face gradients, glow, brushed stripes or
   uneven fading. Light/dark gradients remain only inside actual meter LEDs
   and the original PNG thumbs, never across a panel's surface. */
.window-title{background:#101f28!important;box-shadow:inset 0 -1px #526a743b!important}
.command-bar{background:#1b2d38!important;box-shadow:inset 0 1px #ffffff0b,inset 0 -1px #07131b!important}
.mixer-title{background:#162934!important;box-shadow:inset 0 -1px #5c758039!important}
.console-body .section-rail{box-shadow:inset -1px #07131b!important}
.console-body .section-rail>.rail-cell{border-bottom:1px solid #172a33!important;}
.console-body .strip .section{
 border-bottom:1px solid #102630!important;
 box-shadow:inset 0 -1px #7a98a11b!important;
}
.console-body .strip .subhead,
.console-body .strip .send-header{
 background:#142732!important;
 border-bottom:1px solid #10232c!important;
 box-shadow:inset 0 1px #77939b17!important;
}
.console-body .rail-cell.fader{background:#243641!important}
.console-body .strip .route-caption,
.console-body .strip .subhead .hint{color:#b8cbd5!important}
.console-body .strip .route-select,
.console-body .strip .send-select{background:#0e222d!important}

/* Integration with contemporary V13 WIRE bay. The wire bay may use 160px
   on tall desks; stage laptop uses 148px to protect 4 inserts + fixed fader.
   Wire controls, semantics and dynamic SVG routings are unchanged. */
@media(max-height:820px){
 .console-body.wire-routing-v13:not(.collapsed-send){--send-h:148px!important}
}
.console-body.wire-routing-v13 .section-rail .rail-cell.send{border-top:1px solid #617d8a43!important;
}
/* A carefully restrained physical edge is fine; broad face gradients and
   worn-metal zebra strokes are not. */

/* V14.1 physical hierarchy: three upper modules can close independently.
   SEND close is a TRUE 23px folded header, not a tiny still-active patch bay.
   The source/destination graph belongs to state, not to the SVG or DOM nodes. */
.console-body.wire-routing-v13.collapsed-send{
 --send-h:23px!important;
}
@media(max-height:680px){
 .console-body.wire-routing-v13.collapsed-send{--send-h:23px!important}
}
.console-body.wire-routing-v13.collapsed-send .routing-wire-overlay{
 display:none!important;
}
.console-body.wire-routing-v13.collapsed-send .section-rail .rail-cell.send::after{
 content:"OPEN"!important;
 color:#91bac5!important;
}
/* Dark premium satin graphite: uniform plate colors, no giant highlights.
   Only section borders, actual recessed fader grooves and meter LEDs have
   relief. The physical thumb asset is intentionally untouched. */
.console-body{
 --v13-plate:#182832;
 --v13-route:#172731;
 --v13-insert:#142630;
 --v13-send:#182a34;
 --v13-lower:#192b35;
 --v13-edge:#3e5661;
}
.console-body .strip{
 background:#1b2c36!important;
 border-right:1px solid #0b1a22!important;
 box-shadow:inset 1px 0 #94b4c11b,inset -1px 0 #06121955!important;
}
.console-body .strip.selected{
 background:#20333e!important;
 box-shadow:inset 0 0 0 1px var(--ch),inset 0 0 0 2px #0c1a24!important;
}
.console-body .strip .route-section{background:var(--v13-route)!important}
.console-body .strip .send-section{background:var(--v13-send)!important}
.console-body .strip .pan-section,
.console-body .strip .switch-section{background:var(--v13-lower)!important}
.console-body .strip .bottom-section{background:#182832!important}
.console-body .section-rail{background:#152630!important}
.console-body .section-rail>.rail-cell{
 background:#1a2c37!important;
 box-shadow:inset 0 1px #ffffff08!important;
}
.console-body.wire-routing-v13 .section-rail .rail-cell.send{background:#192d38!important}
